"""Conditional continuous-budget lower bound for the frozen validation surrogate."""
import json,hashlib
from pathlib import Path
import numpy as np
from scipy.optimize import minimize
OUT=Path('results/thrml_spw/sample_allocation')
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
    frozen=sha(OUT/'allocation.json');a=json.loads((OUT/'allocation.json').read_text());s=np.array(a['coefficients'],float);u=np.array(a['weight_units'],float);budget=288.;root=float(np.sqrt(s*u).sum());bound=root**2/budget;optimal=budget*np.sqrt(s/u)/root;assert np.all(s>0) and np.all(u>0);np.testing.assert_allclose(u@optimal,budget,atol=1e-12);np.testing.assert_allclose(np.sum(s/optimal),bound,atol=1e-14)
    reference=minimize(lambda v:float(np.sum(s/v)),np.full(24,4.),jac=lambda v:-s/v**2,bounds=[(1e-6,None)]*24,constraints=[{'type':'eq','fun':lambda v:float(u@v-budget),'jac':lambda v:u}],method='SLSQP',options={'ftol':1e-13,'maxiter':10000});assert reference.success;np.testing.assert_allclose(reference.fun,bound,atol=1e-9,rtol=1e-8)
    raw=np.load(OUT/'validation_baseline.npz');gap=float((raw['mean_nll'].astype(float)-raw['FP32_nll'].astype(float)).mean());headroom=np.log(1.05)-gap;required=root**2/headroom if headroom>0 else None
    assert sha(OUT/'allocation.json')==frozen
    r={'passed_algebra_and_independent_convex_solver_check':True,'frozen_allocation_sha256':frozen,'surrogate_sum_sqrt_coefficient_weight_units_squared':root**2,'continuous_surrogate_minimum_at_budget288':bound,'discrete_frozen_surrogate_objective':a['objective'],'uniform_surrogate_objective':a['uniform_surrogate_objective'],'continuous_optimal_sample_counts':(256*optimal).tolist(),'validation_programmed_mean_minus_FP32_CE':gap,'proxy_minimum_total_CE_gap':gap+bound,'proxy_minimum_relative_perplexity':float(np.exp(gap+bound)),'fixed_CE_target':float(np.log(1.05)),'proxy_CE_target_feasible_at_current_budget':bool(gap+bound<=np.log(1.05)),'continuous_proxy_required_budget_units_for_CE_target':required,'continuous_proxy_required_update_ratio':required/288 if required else None,'independent_solver':'SciPy SLSQP; positive separable convex objective, one linear equality','independent_solver_objective':float(reference.fun),'derivation':'Cauchy-Schwarz: (sum sqrt(S_l*u_l))^2 <= (sum S_l/level_l)*(sum u_l*level_l). Hence objective>=A^2/B. Equality level_l=B*sqrt(S_l/u_l)/A. Continuous relaxation ignores integer sample limits.','source_sha256':sha(__file__),'new_native_samples':0,'test_scores_used':False,'frozen_allocation_changed':False,'scope':'Post-hoc planning diagnostic from validation only. Exact algebraic lower bound of a noisy, floored, separable inverseT proxy, NOT a bound on actual neural loss, encoding capability or hardware performance. No substitute schedule tested or selected; all actual quality failures and the frozen allocation remain unchanged.'};(OUT/'proxy_bound.json').write_text(json.dumps(r,indent=2)+'\n');print(json.dumps({k:v for k,v in r.items() if 'optimal_sample' not in k},indent=2))
if __name__=='__main__':main()
